INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > MongoDB > Aggregation
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Filtert der $match-Operator in der MongoDB-Aggregation Dokumente basierend auf bestimmten Bedingungen?', 2, '[{"text": "Ja", "correct": true, "because": "$match reduziert die Dokumentenmenge nach Kriterien"}, {"text": "Nein", "correct": false, "because": "Definition von $match"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der $group-Operator in MongoDB Daten nach einem bestimmten Feld zusammenfassen und Aggregatfunktionen anwenden?', 2, '[{"text": "Ja", "correct": true, "because": "$group fasst Daten zusammen und aggregiert"}, {"text": "Nein", "correct": false, "because": "Zweck von $group"}]'),
('00000000-0000-0000-0000-000000000000', 'Sortiert der $sort-Operator in der MongoDB-Aggregation die Ergebnisse nach einem oder mehreren Feldern?', 2, '[{"text": "Ja", "correct": true, "because": "$sort ordnet Dokumente nach Feldern"}, {"text": "Nein", "correct": false, "because": "Definition von $sort"}]'),
('00000000-0000-0000-0000-000000000000', 'Beschränkt der $limit-Operator in der MongoDB-Aggregation die Anzahl der zurückgegebenen Dokumente?', 2, '[{"text": "Ja", "correct": true, "because": "$limit begrenzt die Ausgabe"}, {"text": "Nein", "correct": false, "because": "Hauptfunktion von $limit"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss jede Aggregation Pipeline in MongoDB immer alle Operatoren wie $match und $group enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Operatoren sind optional und flexibel kombinierbar"}, {"text": "Ja", "correct": false, "because": "Keine zwingende Reihenfolge"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Operator in der MongoDB-Aggregation filtert Dokumente nach bestimmten Bedingungen?', 2, '[{"text": "$match", "correct": true, "because": "Filtert nach Kriterien"}, {"text": "$group", "correct": false, "because": "Fasst zusammen"}, {"text": "$sort", "correct": false, "because": "Sortiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Operator wird verwendet, um Daten in MongoDB nach einem Feld zu gruppieren und Aggregatfunktionen anzuwenden?', 3, '[{"text": "$group", "correct": true, "because": "Gruppiert und aggregiert"}, {"text": "$match", "correct": false, "because": "Filtert"}, {"text": "$limit", "correct": false, "because": "Begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Operator sortiert die Ergebnisse einer MongoDB-Aggregation?', 2, '[{"text": "$sort", "correct": true, "because": "Sortiert nach Feldern"}, {"text": "$group", "correct": false, "because": "Fasst zusammen"}, {"text": "$match", "correct": false, "because": "Filtert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Operator beschränkt die Anzahl der Dokumente in einer MongoDB-Aggregation?', 2, '[{"text": "$limit", "correct": true, "because": "Begrenzt die Ausgabe"}, {"text": "$sort", "correct": false, "because": "Sortiert"}, {"text": "$group", "correct": false, "because": "Gruppiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Operator ist typischerweise der erste Schritt in einer Aggregation Pipeline, um die Datenmenge zu reduzieren?', 2, '[{"text": "$match", "correct": true, "because": "Filtert frühzeitig"}, {"text": "$limit", "correct": false, "because": "Begrenzt später"}, {"text": "$sort", "correct": false, "because": "Sortiert"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Operatoren gehören zur MongoDB-Aggregation Pipeline?', 4, '[{"text": "$match", "correct": true, "because": "Filtert Dokumente"}, {"text": "$group", "correct": true, "because": "Gruppiert Daten"}, {"text": "$sort", "correct": true, "because": "Sortiert Ergebnisse"}, {"text": "$insert", "correct": false, "because": "CRUD, nicht Aggregation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen kann der $match-Operator in der Aggregation Pipeline erfüllen?', 3, '[{"text": "Daten filtern", "correct": true, "because": "Reduziert nach Bedingungen"}, {"text": "Vergleichsoperatoren nutzen", "correct": true, "because": "$gt, $lt etc."}, {"text": "Logische Bedingungen kombinieren", "correct": true, "because": "$and, $or"}, {"text": "Daten gruppieren", "correct": false, "because": "$group"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat der $group-Operator in MongoDB?', 4, '[{"text": "Gruppiert nach Feldern", "correct": true, "because": "Definiert Gruppen"}, {"text": "Unterstützt Aggregatfunktionen", "correct": true, "because": "$sum, $avg etc."}, {"text": "Erzeugt neue Dokumente", "correct": true, "because": "Gruppierte Ergebnisse"}, {"text": "Sortiert Ergebnisse", "correct": false, "because": "$sort"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen bietet der $sort-Operator in der Aggregation Pipeline?', 3, '[{"text": "Aufsteigende Sortierung", "correct": true, "because": "1 für ASC"}, {"text": "Absteigende Sortierung", "correct": true, "because": "-1 für DESC"}, {"text": "Sortierung nach mehreren Feldern", "correct": true, "because": "Mehrfachsortierung möglich"}, {"text": "Datenbegrenzung", "correct": false, "because": "$limit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat der $limit-Operator in der Aggregation Pipeline?', 3, '[{"text": "Begrenzt die Anzahl der Dokumente", "correct": true, "because": "Reduziert Ausgabe"}, {"text": "Kann mit $sort kombiniert werden", "correct": true, "because": "Sortiert und begrenzt"}, {"text": "Effizient bei großen Datenmengen", "correct": true, "because": "Weniger Datenverarbeitung"}, {"text": "Gruppiert Daten", "correct": false, "because": "$group"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) $match filtert Dokumente in der Aggregation Pipeline. b) Es sortiert die Ergebnisse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Filtert ja, sortiert nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) $group fasst Daten zusammen und aggregiert. b) $limit gruppiert Daten nach Feldern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zusammenfassen ja, begrenzen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) $sort ordnet Dokumente nach Feldern. b) Es ist immer der erste Schritt in der Pipeline.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sortiert ja, erster Schritt nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) $limit reduziert die Anzahl der Ergebnisse. b) $match muss immer vor $group stehen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Reduziert ja, Reihenfolge flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) $group unterstützt Aggregatfunktionen wie $sum. b) $sort begrenzt die Anzahl der Dokumente.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aggregat ja, begrenzen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

